from pathlib import Path
lines = Path('.github/workflows/build.yml').read_text().splitlines()
for job in ('docker-master', 'docker-hardware', 'docker-rockchip'):
    header = lines.index(f'  {job}:')
    if lines[header + 2] != '    if: ${{ false }}':
        raise SystemExit(f'{job} must remain disabled in the legacy workflow')
